def transform(grid):
    # Fill the rectangle's inner field using its border color.
    out = [row[:] for row in grid]
    cells = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v != 0]
    if not cells:
        return out
    r0, r1 = min(r for r, c in cells), max(r for r, c in cells)
    c0, c1 = min(c for r, c in cells), max(c for r, c in cells)
    # The innermost non-background object color expands outward by the thickness
    # of the surrounding region; the former outer region remains unchanged.
    counts = {}
    for row in grid:
        for v in row:
            if v:
                counts[v] = counts.get(v, 0) + 1
    inner_color = min(counts, key=counts.get)
    # Identify the rectangular frame of that color and expand it to the grid
    # edges of the bounding canvas while preserving its original footprint.
    pts = [(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v == inner_color]
    ir0, ir1 = min(r for r,c in pts), max(r for r,c in pts)
    ic0, ic1 = min(c for r,c in pts), max(c for r,c in pts)
    # Infer expansion thickness from the gap between inner object and its outer region.
    pad_top, pad_left = ir0-r0, ic0-c0
    pad_bottom, pad_right = r1-ir1, c1-ic1
    for r in range(max(0,r0-pad_top), min(len(grid),r1+pad_bottom+1)):
        for c in range(max(0,c0-pad_left), min(len(grid[0]),c1+pad_right+1)):
            if r < r0 or r > r1 or c < c0 or c > c1:
                out[r][c] = inner_color
    return out
